async def act(page):
    """
    Find the post using the site helper and leave the comment "Well written and easy to understand.".

    Steps performed:
      1. Use monitor_keyword_and_notify(...) to search the homepage for the requested post.
      2. If found, navigate to the post URL (relative goto when possible).
      3. Locate an accessible comment textbox using role-based selectors (guarded with await count()).
      4. Fill the textbox and attempt to submit using a button scoped to the containing form (full get_by_role path). Fall back to nearby buttons and finally a form.submit() via evaluate().
    """
    comment_text = "Well written and easy to understand."

    # 1) Use the KB helper to find the article on the homepage. The helper navigates to '/' itself.
    try:
        results = await monitor_keyword_and_notify(page, "Rivalries And Rumours", check_interval_minutes=60, notify_via="print", max_results=20)
    except Exception:
        results = []

    # Fallback broader keyword
    if not results:
        try:
            results = await monitor_keyword_and_notify(page, "Murdoch", check_interval_minutes=60, notify_via="print", max_results=20)
        except Exception:
            results = []

    if not results:
        # Could not find the post on the homepage; nothing to do.
        return

    # 2) Open the first matched post's URL
    first = results[0] if isinstance(results, (list, tuple)) and len(results) > 0 else None
    if not isinstance(first, dict):
        return
    post_url = first.get("url")
    if not post_url:
        return

    # Navigate to the post (use relative goto when possible)
    await page.goto(post_url)
    try:
        await page.wait_for_load_state("networkidle", timeout=5000)
    except Exception:
        # continue defensively even if networkidle times out
        pass

    # 3) Locate a comment textbox using accessibility-role-centric selectors (guarded counts)
    comment_locator = None
    candidate_locators = [
        page.get_by_role("textbox", name="Comment"),
        page.get_by_role("textbox", name="Leave a Reply"),
        page.get_by_role("textbox", name="Add a comment"),
        page.get_by_role("textbox", name="Write a comment"),
        page.get_by_role("textbox"),
    ]

    for cand in candidate_locators:
        try:
            if await cand.count() > 0:
                comment_locator = cand.nth(0)
                break
        except Exception:
            continue

    # If not found, look for a textbox inside a role="form" container
    if comment_locator is None:
        try:
            forms = page.get_by_role("form")
            if await forms.count() > 0:
                total = await forms.count()
                for i in range(total):
                    f = forms.nth(i)
                    try:
                        txt = f.get_by_role("textbox")
                        if await txt.count() > 0:
                            comment_locator = txt.nth(0)
                            break
                    except Exception:
                        continue
                    if comment_locator is not None:
                        break
        except Exception:
            pass

    if comment_locator is None:
        # No accessible textbox to leave a comment
        return

    # 4) Fill the comment box
    try:
        await comment_locator.fill(comment_text)
    except Exception:
        try:
            await comment_locator.click()
            await page.keyboard.type(comment_text)
        except Exception:
            return

    # 5) Attempt to submit: prefer a button inside the form that contains the textbox
    submitted = False
    try:
        form_with_textbox = None
        try:
            forms = page.get_by_role("form")
            if await forms.count() > 0:
                total = await forms.count()
                for i in range(total):
                    f = forms.nth(i)
                    try:
                        if await f.get_by_role("textbox").count() > 0:
                            form_with_textbox = f
                            break
                    except Exception:
                        continue
        except Exception:
            form_with_textbox = None

        if form_with_textbox is not None:
            # Use the full get_by_role path to the button to avoid ambiguity
            button_names = ["Post Comment", "Post", "Submit Comment", "Submit", "Send", "Comment"]
            for name in button_names:
                try:
                    btn = form_with_textbox.get_by_role("button", name=name)
                    if await btn.count() > 0:
                        await btn.nth(0).click()
                        submitted = True
                        break
                except Exception:
                    continue
            if not submitted:
                try:
                    btns = form_with_textbox.get_by_role("button")
                    if await btns.count() > 0:
                        await btns.nth(0).click()
                        submitted = True
                except Exception:
                    pass
    except Exception:
        submitted = False

    # 6) If not submitted, try buttons near the textbox or pragmatic fallback
    if not submitted:
        try:
            all_buttons = page.get_by_role("button")
            if await all_buttons.count() > 0:
                nearby = all_buttons.filter(has=comment_locator)
                if await nearby.count() > 0:
                    await nearby.nth(0).click()
                    submitted = True
                else:
                    # pragmatic fallback: click the first visible button on the page
                    await all_buttons.nth(0).click()
                    submitted = True
        except Exception:
            submitted = False

    # 7) Last-resort: submit the closest form via evaluate on the comment element
    if not submitted:
        try:
            attempted = await comment_locator.evaluate(
                "(el) => { const form = el.closest('form'); if(!form) return false; if(typeof form.requestSubmit === 'function'){ form.requestSubmit(); return true;} const submit = form.querySelector('button[type=submit], input[type=submit]'); if(submit){ submit.click(); return true;} try{ form.submit(); return true;}catch(e){return false;} }"
            )
            if attempted:
                submitted = True
        except Exception:
            submitted = False

    return

